const lastRequestTime = {};
const MIN_DELAY_MS = 1500; // Mínimo entre requests al mismo modelo

/**
 * Espera un delay si es necesario para respetar rate limits.
 */
async function throttle(modelName) {
  const now = Date.now();
  const last = lastRequestTime[modelName] || 0;
  const elapsed = now - last;
  if (elapsed < MIN_DELAY_MS) {
