/**
 * prompt_builder.js — Constructor dinámico del System Prompt (Optimizado para bajo consumo de tokens)
 */

function buildSystemPrompt({ tools = [], memoryContext = '', steps = [] }) {
  // Personalidad base ultra-compacta
  let prompt = `Eres J.A.R.V.I.S., asistente personal de escritorio. Llama al usuario "señor". Responde en español. Sé conciso y directo.
Operas en un bucle: Razonar → Herramienta → Observar → Responder.

## HERRAMIENTAS
`;

  if (tools.length === 0) {
    prompt += '(Sin herramientas disponibles.)\n';
  } else {
    // Ultra-compacto: una línea por herramienta
    for (const t of tools) {
      const paramStr = t.params && Object.keys(t.params).length > 0
        ? Object.entries(t.params).map(([k, v]) => `${k}${v.required ? '*' : ''}`).join(',')
        : '';
      prompt += `- ${t.name}(${paramStr}): ${t.description}\n`;
    }
  }

  // Reglas compactas
  prompt += `
## REGLAS
1. Prefiere apps locales (open_app) antes que webs.
2. NUNCA repitas una acción que ya tuvo éxito.
3. Tras un éxito, responde con final_answer INMEDIATAMENTE.
4. Si no puedes, informa al usuario.
`;

  // Memoria (solo si hay)
  if (memoryContext && memoryContext.trim()) {
    prompt += `\n## MEMORIA\n${memoryContext}\n`;
  }

  // Pasos previos (CRÍTICO para evitar bucles)
  if (steps.length > 0) {
    prompt += `\n## PASOS EJECUTADOS\n`;
    for (let i = 0; i < steps.length; i++) {
      const s = steps[i];
      const status = s.result?.success ? '✓ ÉXITO' : '✗ FALLO';
      const resultText = s.result?.success ? s.result.result : (s.result?.error || 'Error desconocido');
      prompt += `${i + 1}. ${s.tool}(${JSON.stringify(s.params)}) → ${status}: ${resultText}\n`;
    }
    prompt += `\nSi ya se cumplió el objetivo, usa final_answer AHORA. NO repitas herramientas.\n`;
  }

  // Formato de respuesta
  prompt += `
## FORMATO (JSON estricto, sin markdown)
Para usar herramienta:
{"thinking":"...","type":"tool_call","tool":"nombre","params":{...}}

Para responder al usuario:
{"thinking":"...","type":"final_answer","answer":"Respuesta para el usuario"}
`;

  return prompt;
}

function buildUserPrompt(objective, conversationHistory = []) {
  let prompt = '';

  if (conversationHistory.length > 0) {
    prompt += 'Conversación reciente:\n';
    for (const msg of conversationHistory.slice(-3)) {
      prompt += `${msg.role === 'user' ? 'Usuario' : 'JARVIS'}: ${msg.content}\n`;
    }
    prompt += '\n';
  }

  prompt += `Objetivo: "${objective}"\n\nResponde con JSON.`;

  return prompt;
}

module.exports = { buildSystemPrompt, buildUserPrompt };
